package com.crosscheck.controller;
import com.crosscheck.model.*;import com.crosscheck.repository.*;import com.crosscheck.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class SystemController{private final NotificationRepository notes;private final AuditLogRepository audits;private final UserRepository users;private final AuthService auth;public SystemController(NotificationRepository n,AuditLogRepository a,UserRepository u,AuthService s){notes=n;audits=a;users=u;auth=s;}@GetMapping("/notifications") public List<Notification> notes(@RequestHeader(value="Authorization",required=false)String h){auth.require(h);return notes.findTop50ByOrderByCreatedAtDesc();}@GetMapping("/audit-logs") public List<AuditLog> logs(@RequestHeader(value="Authorization",required=false)String h){auth.require(h);return audits.findTop100ByOrderByCreatedAtDesc();}@GetMapping("/admin/users") public List<Map<String,Object>> users(@RequestHeader(value="Authorization",required=false)String h){User me=auth.require(h);if(!"ADMIN".equals(me.getRole()))throw new RuntimeException("Forbidden");return users.findAll().stream().map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole(),"active",u.isActive())).toList();}@PostMapping("/admin/users") public Map<String,Object> create(@RequestHeader(value="Authorization",required=false)String h,@RequestBody User u){User me=auth.require(h);if(!"ADMIN".equals(me.getRole()))throw new RuntimeException("Forbidden");u.setId(null);u.setPassword(auth.encode(u.getPassword()));User s=users.save(u);return Map.of("id",s.getId(),"name",s.getName(),"email",s.getEmail(),"role",s.getRole());}}
